mapper.insert:
insert into TRM_COURSE_TEACHER (PLO_NUM, SKILL_TYPE, SKILL_NAME, 
  DATA_DATE, AVATAR, INTRODUCE, 
  COURSE_NUM, COURSE_HOUR, SCORE, 
  STATUS, PLO_NAME, HONOR
  )
values (#{ploNum,jdbcType=VARCHAR}, #{skillType,jdbcType=DECIMAL}, #{skillName,jdbcType=DECIMAL}, 
  #{dataDate,jdbcType=VARCHAR}, #{avatar,jdbcType=VARCHAR}, #{introduce,jdbcType=VARCHAR}, 
  #{courseNum,jdbcType=DECIMAL}, #{courseHour,jdbcType=DECIMAL}, #{score,jdbcType=DECIMAL}, 
  #{status,jdbcType=DECIMAL}, #{ploName,jdbcType=VARCHAR}, #{honor,jdbcType=VARCHAR}
  )

mapper.select:
select

from (
    select

    from TRM_COURSE_TEACHER where STATUS != 0 order by STATUS desc,HONOR,SCORE*COURSE_HOUR*COURSE_NUM desc
    ) where rownum < 13
